/** CLI-owned; regenerated by setu generate module or setu generate … --module <name>. */
import type { IRouterApi, IServiceRegistry } from '@setu-ts/common';
import { registerChatRoutes } from './chat.controller.ts';

/** Registers the feature routes. */
export function registerChatModule(router: IRouterApi, services?: IServiceRegistry): void {
  registerChatRoutes(router, services);
}
